  flora.add(x,h+tr/2,z,.55,tr,.55,0x544b3c);
  for(let level=0;level<3;level++){
    const ww=w-level*.55,y=h+1.7+level*1.25;
    flora.add(x,y,z,ww,1.15,ww,pick([0x234c43,0x2c5b4c,0x1e443e]));
    flora.add(x,y+.64,z,ww*.94,.18,ww*.94,pick([0xe4efed,0xcfdeda]));
  }
  flora.add(x,h+5.25,z,.8,.8,.8,0xe7f0ec);
}
